<?php
// Included only by the disposable-database integration runner.
require_once $workspace.'/models/InventoryControl.php';
$_SESSION['user']=['id'=>1,'branch_id'=>1];
$icProduct=product('Count test','ingredient','g');
RecipeInventory::adjust($icProduct,1,'stock_in','10.5','Opening count fixture',1);
$icKey=bin2hex(random_bytes(16));
$icCount=InventoryControl::record($icProduct,1,'count','8.25','Physical count',$icKey);
check(RecipeInventory::balance($icProduct,1)===105000,'saving a count does not change stock');
check(InventoryControl::record($icProduct,1,'count','8.25','Physical count',$icKey)===$icCount,'count submission retries return original count');
reject(function()use($icProduct,$icKey){InventoryControl::record($icProduct,1,'count','9','Different count',$icKey);},'count request key cannot be reused for changed data');
InventoryControl::resolve($icCount,'reconcile','Confirmed shortage');
InventoryControl::resolve($icCount,'reconcile','Confirmed shortage');
check(RecipeInventory::balance($icProduct,1)===82500,'fractional reconciliation and retry deduct stock exactly once');
$icStale=InventoryControl::record($icProduct,1,'count','7','Before receipt',bin2hex(random_bytes(16)));
RecipeInventory::adjust($icProduct,1,'stock_in','1','Intervening receipt',1);
reject(function()use($icStale){InventoryControl::resolve($icStale,'reconcile','Cannot overwrite receipt');},'reconciliation refuses intervening stock changes');
InventoryControl::resolve($icStale,'dismiss','Recount required');
check(RecipeInventory::balance($icProduct,1)===92500,'dismissal preserves stock');
$icSurplus=InventoryControl::record($icProduct,1,'count','11','Surplus',bin2hex(random_bytes(16)));
InventoryControl::resolve($icSurplus,'reconcile','Verified surplus');
check(RecipeInventory::balance($icProduct,1)===110000,'positive reconciliation creates traceable stock');
$icLossKey=bin2hex(random_bytes(16));
$icLoss=InventoryControl::record($icProduct,1,'damaged','1.5','Broken packaging',$icLossKey);
InventoryControl::record($icProduct,1,'damaged','1.5','Broken packaging',$icLossKey);
check(RecipeInventory::balance($icProduct,1)===95000,'categorized damage loss deducts once');
InventoryControl::record($icProduct,1,'lost','0.5','Missing stock',bin2hex(random_bytes(16)));
check(RecipeInventory::balance($icProduct,1)===90000,'lost stock deducts fractional quantity');
reject(function()use($icProduct){InventoryControl::record($icProduct,1,'expired','1','No expired stock',bin2hex(random_bytes(16)));},'expired loss cannot consume usable stock');
RecipeInventory::adjust($icProduct,1,'stock_in','2','Expired lot',1,'EXPIRED-COUNT',null,'2020-01-01');
InventoryControl::record($icProduct,1,'expired','2','Expired lot disposal',bin2hex(random_bytes(16)));
check(RecipeInventory::balance($icProduct,1)===90000,'expired disposal leaves usable stock intact');
$icReviewsBefore=(int)RecipeInventory::rows('SELECT COUNT(*) n FROM inventory_reviews')[0]['n'];
reject(function()use($icProduct){InventoryControl::record($icProduct,1,'lost','1000','Impossible loss',bin2hex(random_bytes(16)));},'oversized loss is rejected');
check((int)RecipeInventory::rows('SELECT COUNT(*) n FROM inventory_reviews')[0]['n']===$icReviewsBefore,'failed loss rolls back review and movements');
InventoryControl::reorder($icProduct,1,'12.5');
check(RecipeInventory::rows('SELECT reorder_level FROM inventory_reorder_levels WHERE product_id=?','i',[$icProduct])[0]['reorder_level']==='12.5000','separate fractional reorder level persists');
RecipeInventory::query('UPDATE products SET low_stock_threshold=5 WHERE id=?','i',[$icProduct]);
reject(function()use($icProduct){InventoryControl::reorder($icProduct,1,'4');},'reorder level cannot be below minimum');
reject(function()use($icProduct){InventoryControl::record($icProduct,2,'count','1','Other branch',bin2hex(random_bytes(16)));},'counts enforce branch access');
$icPiece=product('Whole count test');
reject(function()use($icPiece){InventoryControl::record($icPiece,1,'count','1.5','Fractional pieces',bin2hex(random_bytes(16)));},'counts require whole quantities for pieces');
$icRecipe=product('Count prepared recipe','recipe','pc','prepared_batch');
$icIngredientBefore=RecipeInventory::balance($icProduct,1);
$icPreparedCount=InventoryControl::record($icRecipe,1,'count','3','Found prepared goods',bin2hex(random_bytes(16)));
InventoryControl::resolve($icPreparedCount,'reconcile','Verified prepared stock');
check(RecipeInventory::balance($icRecipe,1)===30000 && RecipeInventory::balance($icProduct,1)===$icIngredientBefore,'prepared stock count correction does not consume ingredients');
$icVirtual=product('Virtual recipe count','recipe','pc','made_to_order');
reject(function()use($icVirtual){InventoryControl::record($icVirtual,1,'count','1','Virtual count',bin2hex(random_bytes(16)));},'virtual recipe capacity cannot be physically counted');
$icMatched=InventoryControl::record($icProduct,1,'count','9','Matching stock',bin2hex(random_bytes(16)));
check(RecipeInventory::rows('SELECT status FROM inventory_reviews WHERE id=?','i',[$icMatched])[0]['status']==='matched','matching count closes without adjustment');
$icZero=InventoryControl::record($icProduct,1,'count','0','Empty shelf',bin2hex(random_bytes(16)));
InventoryControl::resolve($icZero,'reconcile','Verified empty');
check(RecipeInventory::balance($icProduct,1)===0,'zero physical count can reconcile stock to zero');
$icPermission=RecipeInventory::rows("SELECT id FROM permissions WHERE name='manage_inventory'")[0]['id'];
RecipeInventory::query('DELETE FROM role_permissions WHERE role_id=1 AND permission_id=?','i',[$icPermission]);
reject(function()use($icProduct){InventoryControl::record($icProduct,1,'count','0','Unauthorized',bin2hex(random_bytes(16)));},'inventory controls enforce manage inventory permission');
RecipeInventory::query('INSERT INTO role_permissions(role_id,permission_id) VALUES(1,?)','i',[$icPermission]);
$icPipes=[];
$icProcess=proc_open([PHP_BINARY,$root.'/tools/tests/burger-integration.php','--endpoint',$workspace,'render_products',base64_encode('{}')],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$icPipes);
fclose($icPipes[0]); $icPage=stream_get_contents($icPipes[1]); $icErrors=stream_get_contents($icPipes[2]);
fclose($icPipes[1]); fclose($icPipes[2]); proc_close($icProcess);
check(strpos($icPage,'Stock counts, discrepancies, losses &amp; reorder levels')!==false || strpos($icPage,'Stock counts, discrepancies, losses & reorder levels')!==false,'products page renders inventory control section');
check(strpos($icPage.$icErrors,'Warning:')===false && strpos($icPage.$icErrors,'Fatal error:')===false,'inventory controls render without PHP warnings');
check(strpos($icPage,'list="return_stock_sale_suggestions"')!==false && strpos($icPage,'<datalist id="return_stock_sale_suggestions">')!==false,'sale return input is connected to native datalist suggestions');
$icSuggestions=Sale::stock_return_suggestions();
check(count($icSuggestions)<=100,'sale suggestions are limited to 100 recent records');
foreach ($icSuggestions as $suggestion) {
    $suggestedSale=RecipeInventory::rows('SELECT branch_id FROM sales WHERE id=?','i',[$suggestion['id']])[0];
    if ((int)$suggestedSale['branch_id']!==1 || RecipeInventory::rows('SELECT sale_id FROM inventory_reversals WHERE sale_id=?','i',[$suggestion['id']])) throw new RuntimeException('Sale suggestions exposed another branch or an already returned sale.');
}
check(true,'sale suggestions respect branch access and exclude already returned stock');
$icPostKey=bin2hex(random_bytes(16));
$icPost=endpoint('products',['action'=>'inventory_count','control_branch'=>'1','item_id'=>$icProduct,'quantity'=>'2','notes'=>'Page count submission','request_key'=>$icPostKey]);
check($icPost['flash']['type']==='success' && RecipeInventory::balance($icProduct,1)===0,'products page count submission records without changing stock');
$icPostId=RecipeInventory::rows('SELECT id FROM inventory_reviews WHERE request_key=?','s',[$icPostKey])[0]['id'];
$icResolve=endpoint('products',['action'=>'inventory_resolve','control_branch'=>'1','review_id'=>$icPostId,'resolution'=>'reconcile','notes'=>'Page verified']);
check($icResolve['flash']['type']==='success' && RecipeInventory::balance($icProduct,1)===20000,'products page reconciliation posts through existing CSRF-protected controller');
$icReorderPost=endpoint('products',['action'=>'inventory_reorder','control_branch'=>'1','item_id'=>$icProduct,'quantity'=>'15']);
check($icReorderPost['flash']['type']==='success','products page saves separate reorder setting');
$icLossPost=endpoint('products',['action'=>'inventory_loss','control_branch'=>'1','item_id'=>$icProduct,'quantity'=>'1','loss_kind'=>'lost','notes'=>'Page loss','request_key'=>bin2hex(random_bytes(16))]);
check($icLossPost['flash']['type']==='success' && RecipeInventory::balance($icProduct,1)===10000,'products page loss submission deducts and records category');
